CREATE TABLE IF NOT EXISTS scraped_parts (
  id        BIGINT AUTO_INCREMENT PRIMARY KEY,
  name      VARCHAR(500) NOT NULL,
  sku       VARCHAR(50),
  price     DECIMAL(10,2),
  mrp       DECIMAL(10,2),
  url       VARCHAR(1000),
  slug      VARCHAR(300),
  in_stock  BOOLEAN DEFAULT TRUE,
  stock_qty INT DEFAULT 0
